      "sourcePreview": "data \"aws_region\" \"current\" {}\n\nlocals {\n  environment = [for key, value in var.environment : { name = key, value = value }]\n  secrets     = [for key, value in var.secrets : { name = key, valueFrom = value }]\n}\n\nresource \"aws_ecs_cluster\" \"this\" {\n  name = var.cluster_name\n\n  setting {\n    name  = \"containerInsights\"\n    value = \"enabled\"\n  }\n\n  tags = var.tags\n}\n\nresource \"aws_cloudwatch_log_group\" \"this\" {\n  name              = \"/ecs/${var.cluster_name}/${var.service_name}\"\n  retention_in_days = var.log_retention_days\n\n  tags = var.tags\n}\n\ndata \"aws_iam_policy_document\" \"assume_tasks\" {\n  statement {\n    actions = [\"sts:AssumeRole\"]\n\n    principals {\n      type        = \"Service\"\n      identifiers = [\"ecs-tasks.amazonaws.com\"]\n    }\n  }\n}\n\nresource \"aws_iam_role\" \"execution\" {\n  name               = \"${var.service_name}-execution\"\n  assume_role_policy = data.aws_iam_policy_document.assume_tasks.json\n\n  tags = var.tags\n}\n\nresource \"aws_iam_role_policy_attachment\" \"execution\" {\n  role       = aws_iam_role.execution.name\n  policy_arn = \"arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy\"\n}\n\ndata \"aws_iam_policy_document\" \"read_secrets\" {\n  count = length(var.secrets) > 0 ? 1 : 0\n\n  statement {\n    sid       = \"ReadOnlyReferencedSecrets\"\n    actions   = [\"secretsmanager:GetSecretValue\"]\n    resources = values(var.secrets)\n  }\n}\n\nresource \"aws_iam_role_policy\" \"read_secrets\" {\n  count = length(var.secrets) > 0 ? 1 : 0\n\n  name   = \"read-referenced-secrets\"\n  role   = aws_iam_role.execution.id\n  policy = data.aws_iam_policy_document.read_secrets[0].json\n}\n\nresource \"aws_iam_role\" \"task\" {\n  name               = \"${var.service_name}-task\"\n  assume_role_policy = data.aws_iam_policy_document.assume_tasks.json\n\n  tags = var.tags\n}\n\ndata \"aws_iam_policy_document\" \"task\" {\n  statement {\n    sid       = \"WriteOwnLogs\"\n    actions   = [\"logs:CreateLogStream\", \"logs:PutLogEvents\"]\n    resources = [\"${aws_cloudwatch_log_group.this.arn}:*\"]\n  }\n}\n\nresource \"aws_iam_role_policy\" \"task\" {\n  name   = \"write-own-logs\"\n  role   = aws_iam_role.task.id\n  policy = data.aws_iam_policy_document.task.json\n}\n\nresource \"aws_security_group\" \"service\" {\n  name        = \"${var.service_name}-service\"\n  description = \"Egress for ${var.service_name}; ingress is owned by the load balancer.\"",
